-- backfilled from live schema_migrations on 2026-10-24, CI-016
do $do$
declare v_oid oid; v_def text; v_new text;
begin
 select p.oid into v_oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='costing' and p.proname='rpc_refresh_materials_stores_allocation_snapshot'
   and pg_get_function_identity_arguments(p.oid)='p_period_start date, p_valuation_date date, p_refresh_run_id bigint';
 v_def:=pg_get_functiondef(v_oid);
 v_new:=replace(v_def,
E'    delete from costing.sku_materials_stores_allocation_snapshot s\n    where s.refresh_run_id = p_refresh_run_id;\n\n    insert into costing.sku_materials_stores_allocation_snapshot (',
E'    delete from costing.sku_materials_stores_allocation_snapshot s\n    where s.refresh_run_id = p_refresh_run_id;\n\n    delete from costing.product_internal_source_materials_stores_allocation_snapshot s\n    where s.refresh_run_id = p_refresh_run_id;\n\n    insert into costing.product_internal_source_materials_stores_allocation_snapshot (\n      period_start,valuation_date,refresh_run_id,policy_id,pool_snapshot_id,product_rm_workload_snapshot_id,\n      source_product_id,source_product_name,source_product_base_uom,monthly_internal_demand_base_qty,\n      rm_workload_units,company_eligible_workload_units,workload_share,frozen_pool_amount,allocation_amount,\n      materials_stores_cost_per_base_uom,allocation_status,allocation_reason_code,allocation_note,demand_evidence_json\n    )\n    select v_period_start,p_valuation_date,p_refresh_run_id,rm.policy_id,v_pool.id,rm.id,\n      d.source_product_id,d.source_product_name,d.source_product_base_uom,d.monthly_internal_demand_base_qty,\n      case when rm.rm_evidence_status=''BLOCKED'' or rm.required_rm_line_count=0 then null\n           else rm.rm_complexity_units*d.monthly_internal_demand_base_qty/nullif(rm.rm_reference_output_qty,0) end,\n      x.company_eligible_workload_units,\n      case when rm.rm_evidence_status=''BLOCKED'' or rm.required_rm_line_count=0 or x.company_eligible_workload_units<=0 then null\n           else (rm.rm_complexity_units*d.monthly_internal_demand_base_qty/nullif(rm.rm_reference_output_qty,0))/x.company_eligible_workload_units end,\n      v_pool.total_pool_amount,\n      case when rm.rm_evidence_status=''BLOCKED'' or rm.required_rm_line_count=0 or x.company_eligible_workload_units<=0 then null\n           else v_pool.total_pool_amount*((rm.rm_complexity_units*d.monthly_internal_demand_base_qty/nullif(rm.rm_reference_output_qty,0))/x.company_eligible_workload_units) end,\n      case when rm.rm_evidence_status=''BLOCKED'' or rm.required_rm_line_count=0 or x.company_eligible_workload_units<=0 or d.monthly_internal_demand_base_qty<=0 then null\n           else (v_pool.total_pool_amount*((rm.rm_complexity_units*d.monthly_internal_demand_base_qty/nullif(rm.rm_reference_output_qty,0))/x.company_eligible_workload_units))/d.monthly_internal_demand_base_qty end,\n      case when rm.rm_evidence_status=''BLOCKED'' or rm.required_rm_line_count=0 then ''BLOCKED''\n           when v_pool.pool_status=''REVIEW_REQUIRED'' or rm.rm_evidence_status=''REVIEW_REQUIRED'' or d.monthly_driver_status=''REVIEW_REQUIRED'' then ''REVIEW_REQUIRED''\n           else ''READY'' end,\n      case when rm.rm_evidence_status=''BLOCKED'' then rm.rm_evidence_reason\n           when rm.required_rm_line_count=0 then ''BLOCKED_NO_INTERNAL_SOURCE_RM_WORKLOAD''\n           when v_pool.pool_status=''REVIEW_REQUIRED'' then ''REVIEW_MATERIALS_STORES_POOL''\n           when rm.rm_evidence_status=''REVIEW_REQUIRED'' then rm.rm_evidence_reason\n           when d.monthly_driver_status=''REVIEW_REQUIRED'' then ''REVIEW_INTERNAL_SOURCE_DEMAND''\n           else ''READY_INTERNAL_SOURCE_STORES_ALLOCATION'' end,\n      case when rm.rm_evidence_status=''BLOCKED'' then ''Internal-source Materials / Stores allocation is blocked by RM workload evidence.''\n           when rm.required_rm_line_count=0 then ''Internal-source Product has no positive governed RM handling workload.''\n           else ''Incremental Materials / Stores workload from downstream internal consumption participates in the same frozen company pool.'' end,\n      d.evidence_json\n    from costing.fn_internal_source_product_demand_as_of(v_period_start,p_valuation_date,p_refresh_run_id) d\n    join costing.product_rm_stores_workload_snapshot rm on rm.refresh_run_id=p_refresh_run_id and rm.product_id=d.source_product_id\n    cross join lateral (select max(w.company_eligible_workload_units) company_eligible_workload_units from costing.sku_materials_stores_workload_snapshot w where w.refresh_run_id=p_refresh_run_id) x;\n\n    insert into costing.sku_materials_stores_allocation_snapshot (' );
 if v_new=v_def then raise exception 'Stores internal allocation insertion patch did not match'; end if;
 v_def:=v_new;
 v_new:=replace(v_def,
E'    select coalesce(sum(s.monthly_sku_allocation_amount),0)\n    into v_allocation_sum\n    from costing.sku_materials_stores_allocation_snapshot s\n    where s.refresh_run_id = p_refresh_run_id\n      and s.allocation_status <> ''BLOCKED'';',
E'    select coalesce((select sum(s.monthly_sku_allocation_amount) from costing.sku_materials_stores_allocation_snapshot s where s.refresh_run_id=p_refresh_run_id and s.allocation_status <> ''BLOCKED''),0)\n         + coalesce((select sum(i.allocation_amount) from costing.product_internal_source_materials_stores_allocation_snapshot i where i.refresh_run_id=p_refresh_run_id and i.allocation_status <> ''BLOCKED''),0)\n    into v_allocation_sum;');
 if v_new=v_def then raise exception 'Stores reconciliation patch did not match'; end if;
 execute v_new;
end $do$;